import{_ as s,C as r,o as t,c as n,a0 as o,b as l,w as a,a as d,E as c,a1 as p}from"./chunks/framework.DScjKhBS.js";const y=JSON.parse('{"title":"CodeCommit Bulk Clone — Design Spec","description":"","frontmatter":{},"headers":[],"relativePath":"docs/superpowers/specs/2026-06-08-codecommit-bulk-clone-design.md","filePath":"docs/superpowers/specs/2026-06-08-codecommit-bulk-clone-design.md"}'),h={name:"docs/superpowers/specs/2026-06-08-codecommit-bulk-clone-design.md"};function u(g,e,m,b,k,f){const i=r("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="codecommit-bulk-clone-—-design-spec" tabindex="-1">CodeCommit Bulk Clone — Design Spec <a class="header-anchor" href="#codecommit-bulk-clone-—-design-spec" aria-label="Permalink to &quot;CodeCommit Bulk Clone — Design Spec&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-08<br><strong>Status:</strong> Approved<br><strong>Goal:</strong> Sync all AWS CodeCommit repositories in <code>us-east-1</code> to <code>~/Sites/edi/</code> for local analysis tooling (Cursor, linters, grep, codebase review).</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Some code lives in <a href="https://us-east-1.console.aws.amazon.com/codesuite/codecommit/repositories?region=us-east-1" target="_blank" rel="noreferrer">AWS CodeCommit</a> rather than GitHub/GitLab. Local analysis tooling needs working copies on disk. CodeCommit differs from GitHub/GitLab in discovery (AWS CLI, not <code>gh</code>) and authentication (IAM-backed HTTPS credential helper).</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Decision</th></tr></thead><tbody><tr><td>Target layout</td><td><code>~/Sites/edi/{repositoryName}/</code></td></tr><tr><td>Scope</td><td>All repos in the AWS account, <code>us-east-1</code></td></tr><tr><td>Clone depth</td><td>Shallow (<code>--depth 1</code>) on first clone</td></tr><tr><td>Deepen option</td><td><code>--deepen {name}</code> runs <code>git fetch --unshallow</code> for one repo</td></tr><tr><td>Re-run behaviour</td><td>Clone new repos; <code>git pull --ff-only</code> in existing ones</td></tr><tr><td>Auth</td><td>Existing global git credential helper + <code>aws configure</code> IAM credentials</td></tr></tbody></table><h2 id="approaches-considered" tabindex="-1">Approaches Considered <a class="header-anchor" href="#approaches-considered" aria-label="Permalink to &quot;Approaches Considered&quot;">​</a></h2><h3 id="_1-shell-sync-script-aws-cli-https-auth-selected" tabindex="-1">1. Shell sync script + AWS CLI + HTTPS auth (selected) <a class="header-anchor" href="#_1-shell-sync-script-aws-cli-https-auth-selected" aria-label="Permalink to &quot;1. Shell sync script + AWS CLI + HTTPS auth (selected)&quot;">​</a></h3><p>List repos via <code>aws codecommit list-repositories</code>, clone or pull each into the target root.</p><p><strong>Pros:</strong> Matches working auth setup; no new dependencies; easy to re-run.<br><strong>Cons:</strong> Manual bash error handling; no audit manifest.</p><h3 id="_2-git-remote-codecommit-helper" tabindex="-1">2. <code>git-remote-codecommit</code> helper <a class="header-anchor" href="#_2-git-remote-codecommit-helper" aria-label="Permalink to &quot;2. `git-remote-codecommit` helper&quot;">​</a></h3><p>Clone via <code>codecommit::us-east-1://{name}</code> URLs (<code>pip install git-remote-codecommit</code>).</p><p><strong>Pros:</strong> AWS-recommended; avoids HTTPS credential-helper edge cases.<br><strong>Cons:</strong> Extra install; different from current working setup.</p><h3 id="_3-mirror-to-github-gitlab" tabindex="-1">3. Mirror to GitHub/GitLab <a class="header-anchor" href="#_3-mirror-to-github-gitlab" aria-label="Permalink to &quot;3. Mirror to GitHub/GitLab&quot;">​</a></h3><p>Mirror each CodeCommit repo to a private GitHub org, clone from GitHub locally.</p><p><strong>Pros:</strong> Unified tooling across all code.<br><strong>Cons:</strong> Heavy operational overhead; duplicate storage; overkill for local analysis.</p><p><strong>Recommendation:</strong> Approach 1.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',18)),(t(),l(p,null,{default:a(()=>[c(i,{id:"mermaid-113",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Script%5B%22sync-codecommit-repos.sh%22%5D%0A%20%20%20%20AWS%5B%22AWS%20CLI%5Cncodecommit%20list-repositories%22%5D%0A%20%20%20%20Loop%5B%22For%20each%20repositoryName%22%5D%0A%20%20%20%20Exists%7B%22Directory%5Cnexists%3F%22%7D%0A%20%20%20%20Clone%5B%22git%20clone%20--depth%201%5Cn(HTTPS%20URL)%22%5D%0A%20%20%20%20Pull%5B%22git%20pull%20--ff-only%22%5D%0A%20%20%20%20Deepen%5B%22git%20fetch%20--unshallow%5Cn(optional%20flag)%22%5D%0A%20%20%20%20Sites%5B%22~%2FSites%2Fedi%2F%7Bname%7D%2F%22%5D%0A%0A%20%20%20%20Script%20--%3E%20AWS%20--%3E%20Loop%20--%3E%20Exists%0A%20%20%20%20Exists%20--%3E%7Cno%7C%20Clone%20--%3E%20Sites%0A%20%20%20%20Exists%20--%3E%7Cyes%7C%20Pull%20--%3E%20Sites%0A%20%20%20%20Script%20--%3E%20Deepen%20--%3E%20Sites%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>scripts/sync-codecommit-repos.sh</code></td><td>Entry point: list repos, clone or pull, report summary</td></tr><tr><td>AWS CLI</td><td>Discovery — <code>list-repositories</code>, <code>get-repository</code> for clone URL</td></tr><tr><td>Git + credential helper</td><td>Clone/pull over HTTPS using existing global config</td></tr><tr><td><code>~/Sites/edi/</code></td><td>Local workspace root for analysis tooling</td></tr></tbody></table><h3 id="prerequisites-already-configured" tabindex="-1">Prerequisites (already configured) <a class="header-anchor" href="#prerequisites-already-configured" aria-label="Permalink to &quot;Prerequisites (already configured)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> credential.&quot;https://git-codecommit.us-east-1.amazonaws.com&quot;.helper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;!aws codecommit credential-helper </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> credential.&quot;https://git-codecommit.us-east-1.amazonaws.com&quot;.UseHttpPath</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configure</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Access key, secret, region us-east-1, output json</span></span></code></pre></div><h3 id="clone-url" tabindex="-1">Clone URL <a class="header-anchor" href="#clone-url" aria-label="Permalink to &quot;Clone URL&quot;">​</a></h3><p>Use HTTPS URL from <code>aws codecommit get-repository --repository-name {name}</code> or construct:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://git-codecommit.us-east-1.amazonaws.com/v1/repos/{name}</span></span></code></pre></div><p>The credential helper handles authentication automatically.</p><h3 id="sync-logic-per-repo" tabindex="-1">Sync logic per repo <a class="header-anchor" href="#sync-logic-per-repo" aria-label="Permalink to &quot;Sync logic per repo&quot;">​</a></h3><ol><li>If <code>~/Sites/edi/{name}/</code> does not exist → <code>git clone --depth 1 {https-url} {path}</code></li><li>If it exists and is a git repo → <code>git -C {path} pull --ff-only</code></li><li>If directory exists but is not a git repo → skip with warning</li><li>If <code>--deepen {name}</code> → <code>git -C {path} fetch --unshallow</code> (only if shallow)</li></ol><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Environment variables or flags, with defaults:</p><table tabindex="0"><thead><tr><th>Variable / flag</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>CODECOMMIT_REGION</code></td><td><code>us-east-1</code></td><td>AWS region</td></tr><tr><td><code>CODECOMMIT_ROOT</code></td><td><code>~/Sites/edi</code></td><td>Local clone root</td></tr><tr><td><code>AWS_PROFILE</code></td><td>unset</td><td>Passed through to <code>aws</code> if set</td></tr></tbody></table><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/sync-codecommit-repos.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # sync all repos</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/sync-codecommit-repos.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deepen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-repo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # full history for one repo</span></span></code></pre></div><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><h3 id="pre-flight-checks-fail-fast" tabindex="-1">Pre-flight checks (fail fast) <a class="header-anchor" href="#pre-flight-checks-fail-fast" aria-label="Permalink to &quot;Pre-flight checks (fail fast)&quot;">​</a></h3><ul><li><code>aws</code> CLI present and callable</li><li><code>aws sts get-caller-identity</code> succeeds</li><li>Git credential helper configured for <code>git-codecommit.us-east-1.amazonaws.com</code></li><li>Target root exists or can be created</li></ul><h3 id="per-repo-errors-continue-on-failure" tabindex="-1">Per-repo errors (continue on failure) <a class="header-anchor" href="#per-repo-errors-continue-on-failure" aria-label="Permalink to &quot;Per-repo errors (continue on failure)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Behaviour</th></tr></thead><tbody><tr><td>Clone fails (permissions, network)</td><td>Log error, continue to next repo</td></tr><tr><td>Pull fails (local changes, diverged branch)</td><td>Warn with repo path; do not force; continue</td></tr><tr><td>Non-git directory at expected path</td><td>Warn and skip</td></tr><tr><td>Repo deleted from CodeCommit but still local</td><td>Leave local copy untouched</td></tr></tbody></table><p><strong>Exit code:</strong> <code>0</code> if all repos succeeded; <code>1</code> if any failed.</p><h3 id="summary-output" tabindex="-1">Summary output <a class="header-anchor" href="#summary-output" aria-label="Permalink to &quot;Summary output&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Synced 12 repos: 3 cloned, 8 pulled, 1 failed</span></span>
<span class="line"><span>Failed: legacy-archive (permission denied)</span></span>
<span class="line"><span>Root: ~/Sites/edi</span></span></code></pre></div><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Manual checks (no automated test suite):</p><ol><li><code>aws codecommit list-repositories --region us-east-1</code> — repo count matches console</li><li>First sync — directories appear under <code>~/Sites/edi/</code></li><li>Re-run — existing repos pull, no duplicate clones</li><li>Open one repo in Cursor — indexing works</li><li><code>--deepen one-repo</code> — <code>git log</code> shows full history</li></ol><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Multi-region support</li><li>Allowlists / blocklists</li><li>Auto-deleting stale local repos</li><li>Mirroring to GitHub/GitLab</li><li>Parallel clones (add later if repo count is large)</li></ul>`,28))])}const S=s(h,[["render",u]]);export{y as __pageData,S as default};
